drop function if exists public.business_set_promotion_active(uuid,uuid,boolean); drop function if exists public.business_set_partner_enabled(uuid,uuid,boolean); drop function if exists public.business_set_qr_active(uuid,uuid,boolean); drop function if exists public.business_reply_review(uuid,uuid,text); drop function if exists public.business_update_location(uuid,uuid,text,text,text,text,boolean); create or replace function public.business_admin_allowed(p_business_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role::text in ('owner','admin')); $$; create function public.business_update_location(p_business_id uuid,p_location_id uuid,p_name text,p_address text,p_city text,p_state text,p_is_active boolean) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_admin_allowed(p_business_id) then raise exception 'Admin access required'; end if; update locations set name=coalesce(p_name,name),address=coalesce(p_address,address),city=coalesce(p_city,city),state=coalesce(p_state,state),is_active=coalesce(p_is_active,is_active) where id=p_location_id and business_id=p_business_id; return (select to_jsonb(l) from locations l where l.id=p_location_id); end; $$; create function public.business_set_promotion_active(p_business_id uuid,p_promotion_id uuid,p_active boolean) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_admin_allowed(p_business_id) then raise exception 'Admin access required'; end if; update promotions set active=p_active where id=p_promotion_id and business_id=p_business_id; return (select to_jsonb(p) from promotions p where p.id=p_promotion_id); end; $$; create function public.business_set_partner_enabled(p_business_id uuid,p_program_id uuid,p_enabled boolean) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_admin_allowed(p_business_id) then raise exception 'Admin access required'; end if; update partner_programs set enabled=p_enabled where id=p_program_id and business_id=p_business_id; return (select to_jsonb(p) from partner_programs p where p.id=p_program_id); end; $$; create function public.business_set_qr_active(p_business_id uuid,p_qr_id uuid,p_active boolean) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_admin_allowed(p_business_id) then raise exception 'Admin access required'; end if; update qr_codes q set active=p_active from locations l where q.id=p_qr_id and q.location_id=l.id and l.business_id=p_business_id; return (select to_jsonb(q) from qr_codes q where q.id=p_qr_id); end; $$; create function public.business_reply_review(p_business_id uuid,p_review_id uuid,p_reply text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.business_admin_allowed(p_business_id) then raise exception 'Admin access required'; end if; update reviews r set business_reply=p_reply where r.id=p_review_id and exists(select 1 from locations l where l.id=r.location_id and l.business_id=p_business_id); return (select to_jsonb(r) from reviews r where r.id=p_review_id); end; $$;
